import sys
import json
from tinyver import Tinyver

def status(pins, advisories=None):
    for pin in pins:
        try:
            t = Tinyver(pin)
            print(f'{pin} is {t.status()}')
        except ValueError as e:
            print(f'Error: {e}', file=sys.stderr)
            sys.exit(2)

    if advisories:
        affected = False
        for advisory in advisories:
            for component, version_range in advisory['affected'].items():
                if component in pins and Tinyver(pins[component]).matches(version_range):
                    affected = True
                    print(f'{advisory['id']} {component} {pins[component]} {advisory['summary']}')
        if affected:
            sys.exit(1)
        else:
            print('no pinned component is affected by an advisory')
            sys.exit(0)

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('Usage: pinwatch <command> [<args>]', file=sys.stderr)
        sys.exit(2)
    command = sys.argv[1]
    if command == 'status':
        pins = json.load(open('data/pins.json'))
        advisories = json.load(open('data/advisories.json')) if len(sys.argv) > 2 and sys.argv[2] == '--advisories' else None
        status(pins, advisories)
    elif command == 'check':
        pins = json.load(open('data/pins.json'))
        status(pins)
    elif command == 'latest':
        pins = json.load(open('data/pins.json'))
        for component, version in pins.items():
            try:
                t = Tinyver(version)
                print(f'{component} {t.latest()}')
            except ValueError as e:
                print(f'Error: {e}', file=sys.stderr)
                sys.exit(2)
    elif command == 'audit':
        pins = json.load(open('data/pins.json'))
        advisories = json.load(open('data/advisories.json'))
        status(pins, advisories)
    else:
        print(f'Unknown command: {command}', file=sys.stderr)
        sys.exit(2)

